selector_to_html = {"a[href=\"#module-pyskyfire.turbine.axial\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.turbine.axial<a class=\"headerlink\" href=\"#module-pyskyfire.turbine.axial\" title=\"Link to this heading\">\u00b6</a></h1><p>Meanline design of an axial turbine, from its duty to a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">TurbineDefinition</span></code>.</p><p>The design runs at mean radius, which is the same at every station, so blade\nspeed is too. Each stage is a stator and a rotor, and for each one you choose:</p>", "a[href=\"StationFlow.html#pyskyfire.turbine.axial.StationFlow\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.axial.StationFlow\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.axial.</span></span><span class=\"sig-name descname\"><span class=\"pre\">StationFlow</span></span></dt><dd><p>The flow at mean radius between two rows (or at either end).</p><p>Angles are radians from axial, positive in the rotation direction.\nRelative quantities use the blade speed <code class=\"docutils literal notranslate\"><span class=\"pre\">u</span></code>, which is the same at every\nstation; they only mean something next to a rotor.</p></dd>", "a[href=\"AxialTurbine.html#pyskyfire.turbine.axial.AxialTurbine\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.axial.AxialTurbine\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.axial.</span></span><span class=\"sig-name descname\"><span class=\"pre\">AxialTurbine</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">duty</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">efficiency</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">stages</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mean_diameter</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_jet_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">work_split</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_swirl</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">loss_split</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rows</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">COUNTERCLOCKWISE</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Design an axial turbine at mean radius. See the module docstring.</p></dd>", "a[href=\"StageFlow.html#pyskyfire.turbine.axial.StageFlow\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.axial.StageFlow\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.axial.</span></span><span class=\"sig-name descname\"><span class=\"pre\">StageFlow</span></span></dt><dd><p>One stage\u2019s triangles: stator inlet (1), rotor inlet (2), rotor exit (3).</p></dd>", "a[href=\"SectionProfile.html#pyskyfire.turbine.axial.SectionProfile\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.axial.SectionProfile\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.axial.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SectionProfile</span></span></dt><dd><p>The section shape of one kind of row, in fractions of its chord.</p></dd>", "a[href=\"RowSettings.html#pyskyfire.turbine.axial.RowSettings\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.axial.RowSettings\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.axial.</span></span><span class=\"sig-name descname\"><span class=\"pre\">RowSettings</span></span></dt><dd><p>How the triangles become blades.</p></dd>", "a[href=\"Stage.html#pyskyfire.turbine.axial.Stage\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.axial.Stage\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.axial.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Stage</span></span></dt><dd><p>The velocity-triangle choices for one stage.</p><p>Give <code class=\"docutils literal notranslate\"><span class=\"pre\">reaction</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">exit_swirl</span></code>, not both.</p></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
